// Confere o cabeçalho X-ZenTrade-Assinatura e o prazo, exatamente como verificar()
// de @zentrade/contratos. O HMAC em si sai do nó Crypto seguinte, que guarda o
// segredo numa credencial do n8n (nunca no fluxo).
const TOLERANCIA_SEGUNDOS = 300;

const item = $input.first().json;
const corpo = typeof item.corpoBruto === 'string' ? item.corpoBruto : '';
const cabecalho = (item.headers || {})['x-zentrade-assinatura'];
const agoraSegundos = Math.floor(Date.now() / 1000);

let formatoOk = false;
let prazoOk = false;
let recebida = '';
let mensagem = '';
if (cabecalho) {
  const partes = Object.fromEntries(String(cabecalho).split(',').map((p) => p.split('=', 2)));
  const t = Number(partes.t);
  recebida = typeof partes.v1 === 'string' ? partes.v1 : '';
  formatoOk = Number.isInteger(t) && /^[0-9a-f]{64}$/.test(recebida);
  if (formatoOk) {
    prazoOk = Math.abs(agoraSegundos - t) <= TOLERANCIA_SEGUNDOS;
    mensagem = `${t}.${corpo}`;
  }
}

return [{ json: { corpo, recebida, formatoOk, prazoOk, mensagem } }];

// Compara o HMAC esperado (nó Crypto) com o recebido em tempo constante e só então
// interpreta o corpo. Corpo sem assinatura válida nunca é lido.
const item = $input.first().json;

const iguais = (a, b) => {
  if (typeof a !== 'string' || typeof b !== 'string' || a.length !== b.length) return false;
  let diferenca = 0;
  for (let i = 0; i < a.length; i++) diferenca |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diferenca === 0;
};

const valida = item.formatoOk === true && item.prazoOk === true && iguais(item.esperada, item.recebida);
let dados = null;
if (valida) {
  try {
    dados = JSON.parse(item.corpo);
  } catch {
    dados = null;
  }
}

return [{ json: { valida, dados } }];

// Valida o corpo como PropostaCriada (@zentrade/contratos) e monta o pedido de
// aprovação. A espera nunca passa de 5 minutos nem do prazo da decisão.
const ESPERA_MAXIMA_MS = 5 * 60 * 1000;
const FOLGA_MINIMA_MS = 10 * 1000;
const LEMBRAR_PROPOSTAS_MS = 60 * 60 * 1000;

const agora = Date.now();
const p = $input.first().json.dados;
const id = (v) => typeof v === 'string' && v.length >= 1 && v.length <= 64;

const problemas = [];
if (!p || typeof p !== 'object' || Array.isArray(p)) {
  problemas.push('o corpo precisa ser um objeto');
} else {
  if (!id(p.decisaoId)) problemas.push('decisaoId');
  if (!id(p.roboId)) problemas.push('roboId');
  if (typeof p.simbolo !== 'string') problemas.push('simbolo');
  if (p.acao !== 'COMPRAR' && p.acao !== 'VENDER') problemas.push('acao');
  if (typeof p.quantidade !== 'string') problemas.push('quantidade');
  if (typeof p.preco !== 'string') problemas.push('preco');
  if (typeof p.resumo !== 'string' || p.resumo.length > 1000) problemas.push('resumo');
  if (!Number.isSafeInteger(p.expiraEm) || p.expiraEm < 0) problemas.push('expiraEm');
}
if (problemas.length > 0) {
  return [{ json: { ok: false, motivo: `campos inválidos: ${problemas.join(', ')}` } }];
}

const proposta = {
  decisaoId: p.decisaoId,
  roboId: p.roboId,
  simbolo: p.simbolo,
  acao: p.acao,
  quantidade: p.quantidade,
  preco: p.preco,
  resumo: p.resumo,
  expiraEm: p.expiraEm,
};

// A mesma proposta reenviada dentro do prazo da assinatura não gera segunda mensagem.
const estado = $getWorkflowStaticData('global');
const vistas = { ...(estado.propostasVistas || {}) };
for (const [chave, em] of Object.entries(vistas)) {
  if (agora - em > LEMBRAR_PROPOSTAS_MS) delete vistas[chave];
}
const duplicada = vistas[proposta.decisaoId] !== undefined;
vistas[proposta.decisaoId] = agora;
estado.propostasVistas = vistas;

const limite = Math.min(proposta.expiraEm, agora + ESPERA_MAXIMA_MS);
const hora = (ms) =>
  new Date(ms).toLocaleTimeString('pt-BR', {
    timeZone: 'America/Sao_Paulo',
    hour: '2-digit',
    minute: '2-digit',
  });
// O nó "enviar e esperar" do Telegram força Markdown e escapa HTML por conta própria:
// troca os caracteres que ele estragaria e protege os especiais do Markdown.
const paraTelegram = (s) =>
  String(s)
    .replace(/&/g, 'e')
    .replace(/</g, '‹')
    .replace(/>/g, '›')
    .replace(/"/g, '”')
    .replace(/'/g, '’')
    .replace(/([_*`\[])/g, '\\$1');
const verbo = proposta.acao === 'COMPRAR' ? 'Comprar' : 'Vender';
const mensagem = [
  'ZenTrade pede sua aprovação',
  '',
  `${verbo} ${proposta.quantidade} ${proposta.simbolo} a cerca de ${proposta.preco}`,
  `Robô: ${proposta.roboId}`,
  `Por quê: ${proposta.resumo || '(sem resumo)'}`,
  '',
  `Responda até ${hora(limite)} (horário de Brasília). Sem resposta, nada é feito.`,
  `Decisão ${proposta.decisaoId}`,
]
  .map(paraTelegram)
  .join('\n');

return [
  {
    json: {
      ok: true,
      duplicada,
      aindaVale: proposta.expiraEm - agora > FOLGA_MINIMA_MS,
      limiteEspera: new Date(limite).toISOString(),
      proposta,
      mensagem,
    },
  },
];

// Transforma o clique no Telegram em RespostaAprovacao (@zentrade/contratos) e
// prepara a assinatura. Sem clique (tempo esgotado) não sai nada: a decisão
// expira sozinha no motor.
const resposta = $input.first().json.data;
const proposta = $('Ler proposta').first().json.proposta;

if (!resposta || typeof resposta.approved !== 'boolean') return [];
if (Date.now() >= proposta.expiraEm) return [];

const r = resposta.responder;
const quem = r ? (r.username ? `@${r.username}` : r.name || r.id || 'desconhecido') : 'link';
const corpo = JSON.stringify({
  decisaoId: proposta.decisaoId,
  aprovada: resposta.approved,
  porQuem: `telegram:${quem}`.slice(0, 80),
});
const carimbo = Math.floor(Date.now() / 1000);

return [{ json: { aprovada: resposta.approved, corpo, carimbo, mensagem: `${carimbo}.${corpo}` } }];
